    --out "step4_sched04n2_chg_c2_rint${MPM_S4_RINT:-50}_ds${MPM_S4_DS:-3e-15}.npz" --viz-out "step4_sched04n2_viz_chg_c2_rint${MPM_S4_RINT:-50}_ds${MPM_S4_DS:-3e-15}.json" \
